WITH kept_keys AS (SELECT category FROM products EXCEPT ALL SELECT category FROM products WHERE brand IN ('Umbrella', 'Acme')), verified AS (SELECT s.* FROM products s INNER JOIN kept_keys k ON s.category = k.category), joined AS (SELECT src.*, p.city, p.rating, p.country FROM verified src LEFT JOIN suppliers p ON src.supplier_id = p.id), remaining_keys AS (SELECT supplier_id, brand FROM joined EXCEPT ALL SELECT supplier_id, brand FROM products WHERE brand = 'Initech'), kept_rows AS (SELECT s.* FROM joined s INNER JOIN remaining_keys k ON s.supplier_id = k.supplier_id AND s.brand = k.brand), enriched AS (SELECT e.*, p.rating AS supplier_rating, p.country AS supplier_country FROM kept_rows e LEFT JOIN suppliers p ON e.supplier_id <=> p.id WHERE p.city = 'Berlin'), scored AS (SELECT brand, cost, stock_qty, supplier_id, rating, country, AVG(price) OVER w_hist AS brand_avg_price, CORR(price, cost) OVER (PARTITION BY supplier_country) AS corr_price_cost, DENSE_RANK() OVER (PARTITION BY category ORDER BY stock_qty DESC NULLS FIRST) AS stock_qty_dense_rank, ROUND(rating / SUM(rating) OVER (PARTITION BY brand, country), 4) AS rating_share FROM enriched WINDOW w_hist AS (PARTITION BY brand)), remaining_keys_2 AS (SELECT brand FROM scored EXCEPT ALL SELECT brand FROM products WHERE category <> 'Books'), verified_products AS (SELECT s.* FROM scored s INNER JOIN remaining_keys_2 k ON s.brand = k.brand), enriched_products AS (SELECT *, RANK() OVER (PARTITION BY country ORDER BY rating_share) AS rating_share_rank, MIN(corr_price_cost) OVER w_running AS supplier_id_min_corr_price_cost, SUM(corr_price_cost) OVER w_ordered AS brand_sum_corr_price_cost, SUM(stock_qty) OVER w_ordered AS brand_sum_stock_qty, DENSE_RANK() OVER w_recent AS stock_qty_dense_rank_dense_rank FROM verified_products WINDOW w_running AS (PARTITION BY supplier_id), w_ordered AS (PARTITION BY brand), w_recent AS (PARTITION BY brand ORDER BY stock_qty_dense_rank DESC NULLS FIRST)) SELECT d.country AS supplier_country, e.brand, COUNT(*) AS rows_total, MAX(e.rating) AS max_rating, MAX(e.cost) AS max_cost FROM enriched_products e LEFT JOIN suppliers d ON e.supplier_id = d.id GROUP BY d.country, e.brand ORDER BY supplier_country DESC;
